"use client"

import { Users, Search, Plus, Activity } from "lucide-react"
import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { db, createPatient } from "@/firebase"
import { 
  collection, 
  query, 
  where, 
  getDocs,
  addDoc,
  Timestamp,
  orderBy,
  limit
} from "firebase/firestore"
import { useAuth } from "@/hooks/use-auth"
console.log("Debug: Loaded DoctorPatientsPage component");
interface Patient {
  id: string
  name: string
  age: number
  status: string
  lastVisit: string
  email: string
  phone: string
  bloodType?: string
}

export default function DoctorPatientsPage() {
  const { user } = useAuth()
  const [searchTerm, setSearchTerm] = useState("")
  const [showAddPatient, setShowAddPatient] = useState(false)
  const [patients, setPatients] = useState<Patient[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const router = useRouter()

  useEffect(() => {
    if (user?.id) {
      fetchPatients()
    }
  }, [user?.id])

  const fetchPatients = async () => {
    if (!user?.id) {
      setError("User not authenticated")
      setLoading(false)
      return
    }

    try {
      setLoading(true)
      setError(null)

      const patientsQuery = query(
        collection(db, 'patients'),
        where('assignedDoctor', '==', user.id)
      )
      
      const patientsSnapshot = await getDocs(patientsQuery)
      
      if (patientsSnapshot.empty) {
        setPatients([])
        setLoading(false)
        return
      }

      const patientsData: Patient[] = []

      for (const doc of patientsSnapshot.docs) {
        const data = doc.data()
        
        // Get last visit from audit logs with better error handling
        let lastVisit = 'Never'
        try {
          const logsQuery = query(
            collection(db, 'audit_logs'),
            where('patientId', '==', doc.id),
            orderBy('timestamp', 'desc'),
            limit(1)
          )
          const logsSnapshot = await getDocs(logsQuery)
          
          if (!logsSnapshot.empty) {
            const lastLog = logsSnapshot.docs[0].data()
            if (lastLog.timestamp) {
              const timestamp = lastLog.timestamp.toDate ? 
                lastLog.timestamp.toDate() : 
                new Date(lastLog.timestamp)
              lastVisit = timestamp.toLocaleDateString()
            }
          }
        } catch (logError) {
          console.warn('Error fetching logs for patient:', doc.id, logError)
          // Continue with default 'Never' value
        }

        // Calculate age from DOB
        let age = 0
        if (data.dob) {
          try {
            const birthDate = new Date(data.dob)
            const today = new Date()
            age = today.getFullYear() - birthDate.getFullYear()
            const monthDiff = today.getMonth() - birthDate.getMonth()
            if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
              age--
            }
          } catch (dobError) {
            console.warn('Error calculating age:', dobError)
          }
        }

        // Determine status based on last activity
        let status = 'Active'
        if (data.lastUpdated) {
          try {
            const lastUpdateTime = data.lastUpdated.toDate ? 
              data.lastUpdated.toDate().getTime() : 
              new Date(data.lastUpdated).getTime()
            const daysSinceUpdate = (Date.now() - lastUpdateTime) / (1000 * 60 * 60 * 24)
            status = daysSinceUpdate < 30 ? 'Active' : 'Inactive'
          } catch (statusError) {
            console.warn('Error determining status:', statusError)
          }
        }

        patientsData.push({
          id: doc.id,
          name: data.name || 'Unknown',
          age: age,
          status: status,
          lastVisit: lastVisit,
          email: data.email || '',
          phone: data.phone || '',
          bloodType: data.bloodType
        })
      }

      setPatients(patientsData)
      setLoading(false)
    } catch (error) {
      console.error('Error fetching patients:', error)
      setError('Failed to load patients. Please try again.')
      setLoading(false)
    }
  }

  const filteredPatients = patients.filter((p) => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.id.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const handleAddPatient = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    const formData = new FormData(e.currentTarget)
    
    try {
      const patientData = {
        id: `PAT-${Date.now()}`,
        name: formData.get('name') as string,
        email: formData.get('email') as string,
        phone: formData.get('phone') as string,
        dob: formData.get('dob') as string,
        bloodType: formData.get('bloodType') as string || 'O+',
        password: 'SafeMedi2025!', // Default password - patient should change
        assignedDoctor: user?.id || '',
        assignedNurse: ''
      }

      await createPatient(patientData)

      // Create alert for new patient
      try {
        await addDoc(collection(db, 'alerts'), {
          type: 'New Patient',
          message: `New patient ${patientData.name} added to your care`,
          severity: 'low',
          timestamp: Timestamp.now(),
          doctorId: user?.id,
          patientId: patientData.id,
          resolved: false
        })
      } catch (alertError) {
        console.warn('Failed to create alert:', alertError)
      }

      // Log the action
      try {
        await addDoc(collection(db, 'audit_logs'), {
          userId: user?.id,
          userName: user?.name,
          action: 'PATIENT_ADDED',
          targetType: 'patient',
          targetId: patientData.id,
          patientName: patientData.name,
          timestamp: Timestamp.now(),
          details: `Patient ${patientData.name} added by ${user?.name}`
        })
      } catch (logError) {
        console.warn('Failed to create audit log:', logError)
      }

      setShowAddPatient(false)
      alert(`✅ Patient added successfully!\n\nPatient ID: ${patientData.id}\nDefault Password: SafeMedi2025!\n\nPlease share these credentials with the patient.`)
      
      // Refresh list
      await fetchPatients()
    } catch (error: any) {
      console.error('Error adding patient:', error)
      alert(`❌ Failed to add patient: ${error.message || 'Unknown error'}`)
    }
  }

  const handleSendMessage = async (patient: Patient) => {
    try {
      // Log message action
      await addDoc(collection(db, 'audit_logs'), {
        userId: user?.id,
        userName: user?.name,
        action: 'MESSAGE_SENT',
        targetType: 'patient',
        targetId: patient.id,
        patientName: patient.name,
        timestamp: Timestamp.now(),
        details: `Message sent to ${patient.name}`
      })

      alert(`✉️ Message sent to ${patient.name}`)
    } catch (error) {
      console.error('Error sending message:', error)
      alert('Failed to send message')
    }
  }

  const handleViewPatient = (patient: Patient) => {
    // Store patient ID for EHR view
    sessionStorage.setItem('selectedPatientId', patient.id)
    router.push("/doctor/ehr")
  }

  if (loading) {
    return (
      <div className="p-8">
        <div className="flex items-center justify-center h-64">
          <div className="text-center">
            <Activity className="h-8 w-8 animate-spin text-primary mx-auto mb-4" />
            <p className="text-secondary">Loading patients...</p>
          </div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="p-8">
        <div className="card p-6 bg-red-50 border-red-200">
          <p className="text-red-700">⚠️ {error}</p>
          <button 
            onClick={fetchPatients}
            className="mt-4 btn-primary"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="p-8">
      {/* Header */}
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-foreground">My Patients</h1>
          <p className="mt-2 text-secondary">
            Manage your patient list ({patients.length} total)
          </p>
        </div>
        <button
          onClick={() => setShowAddPatient(true)}
          className="flex items-center gap-2 rounded-lg bg-gradient-primary px-6 py-2.5 font-semibold text-white transition-all duration-300 hover:shadow-lg"
        >
          <Plus className="h-5 w-5" />
          Add Patient
        </button>
      </div>

      {/* Search */}
      <div className="card mb-6 p-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-secondary" />
          <input
            type="text"
            placeholder="Search patients by name, email, or ID..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="input-field pl-10"
          />
        </div>
      </div>

      {/* Patients Grid */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
        {filteredPatients.length === 0 ? (
          <div className="col-span-full text-center py-12">
            <Users className="h-16 w-16 text-secondary mx-auto mb-4 opacity-50" />
            <p className="text-secondary">
              {searchTerm ? 'No patients match your search' : 'No patients assigned yet'}
            </p>
            {!searchTerm && (
              <button
                onClick={() => setShowAddPatient(true)}
                className="mt-4 btn-primary"
              >
                Add Your First Patient
              </button>
            )}
          </div>
        ) : (
          filteredPatients.map((patient) => (
            <div key={patient.id} className="card p-6 hover:shadow-lg transition-all duration-200">
              <div className="mb-4 flex items-center justify-between">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gradient-primary">
                  <Users className="h-6 w-6 text-white" />
                </div>
                <span
                  className={`inline-block rounded-full px-3 py-1 text-xs font-medium ${
                    patient.status === "Active" 
                      ? "bg-green-100 text-green-700" 
                      : "bg-gray-100 text-gray-700"
                  }`}
                >
                  {patient.status}
                </span>
              </div>
              <h3 className="text-lg font-semibold text-foreground">{patient.name}</h3>
              <p className="mt-1 text-sm text-secondary">ID: {patient.id}</p>
              <p className="text-sm text-secondary">Age: {patient.age || 'N/A'}</p>
              {patient.bloodType && (
                <p className="text-sm text-secondary">Blood Type: {patient.bloodType}</p>
              )}
              <p className="text-sm text-secondary">Last visit: {patient.lastVisit}</p>
              <p className="text-sm text-secondary mt-1">{patient.email}</p>
              <div className="mt-4 flex gap-2">
                <button
                  onClick={() => handleViewPatient(patient)}
                  className="flex-1 rounded-lg bg-blue-50 px-3 py-2 text-sm font-medium text-blue-700 transition-all duration-200 hover:bg-blue-100"
                >
                  View Records
                </button>
                <button
                  onClick={() => handleSendMessage(patient)}
                  className="flex-1 rounded-lg bg-green-50 px-3 py-2 text-sm font-medium text-green-700 transition-all duration-200 hover:bg-green-100"
                >
                  Message
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Add Patient Modal */}
      {showAddPatient && (
        <div className="fixed inset-0 flex items-center justify-center bg-black/50 z-50">
          <div className="card p-6 max-w-md w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold text-foreground mb-2">Add New Patient</h3>
            <p className="text-sm text-secondary mb-4">
              Default password will be: <span className="font-mono font-semibold">SafeMedi2025!</span>
            </p>
            <form onSubmit={handleAddPatient} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">
                  Patient Name *
                </label>
                <input 
                  type="text" 
                  name="name"
                  placeholder="Enter patient name" 
                  className="input-field" 
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">
                  Email *
                </label>
                <input 
                  type="email" 
                  name="email"
                  placeholder="patient@example.com" 
                  className="input-field" 
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">
                  Phone *
                </label>
                <input 
                  type="tel" 
                  name="phone"
                  placeholder="(555) 123-4567" 
                  className="input-field" 
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">
                  Date of Birth *
                </label>
                <input 
                  type="date" 
                  name="dob"
                  className="input-field" 
                  required
                  max={new Date().toISOString().split('T')[0]}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">
                  Blood Type
                </label>
                <select name="bloodType" className="input-field">
                  <option value="O+">O+</option>
                  <option value="O-">O-</option>
                  <option value="A+">A+</option>
                  <option value="A-">A-</option>
                  <option value="B+">B+</option>
                  <option value="B-">B-</option>
                  <option value="AB+">AB+</option>
                  <option value="AB-">AB-</option>
                </select>
              </div>
              <div className="flex gap-3 pt-4">
                <button 
                  type="button"
                  onClick={() => setShowAddPatient(false)} 
                  className="btn-secondary flex-1"
                >
                  Cancel
                </button>
                <button type="submit" className="btn-primary flex-1">
                  Add Patient
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}